diff --git a/panic.go b/panic.go
index 4167329..f827322 100644
--- a/panic.go
+++ b/panic.go
@@ -62,5 +62,12 @@ type CaughtPanic struct {
 }

 func (c *CaughtPanic) Error() string {
-	return fmt.Sprintf("original value: %q\nstacktrace: %s", c.Value, c.Stack)
+	return fmt.Sprintf("panic: %q\nstacktrace:\n%s\n", c.Value, c.Stack)
+}
+
+func (c *CaughtPanic) Unwrap() error {
+	if err, ok := c.Value.(error); ok {
+		return err
+	}
+	return nil
 }
diff --git a/waitgroup_test.go b/waitgroup_test.go
index 4874885..0165070 100644
--- a/waitgroup_test.go
+++ b/waitgroup_test.go
@@ -52,5 +52,21 @@ func TestWaitGroup(t *testing.T) {
 			}
 			require.Panics(t, wg.Wait)
 		})
+
+		t.Run("nonpanics run successfully", func(t *testing.T) {
+			var wg WaitGroup
+			var i atomic.Int64
+			wg.Go(func() {
+				i.Add(1)
+			})
+			wg.Go(func() {
+				panic("super bad thing")
+			})
+			wg.Go(func() {
+				i.Add(1)
+			})
+			require.Panics(t, wg.Wait)
+			require.Equal(t, int64(2), i.Load())
+		})
 	})
 }
